reference_turn1:
Có thể là các giải pháp đơn giản như sử dụng Counter

Câu trả lời mẫu:
```
import os
import re
from collections import Counter
def get_files_in_directory(directory):
    return [os.path.join(directory, f) for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f)) and f.endswith('.txt')]
def read_file(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        return file.read()
def count_words(text):
    words = re.findall(r'\w+', text.lower())
    return Counter(words)
def main():
    directory = input("Enter the directory path: ")
    files = get_files_in_directory(directory)
    word_counts = Counter()
    for file in files:
        text = read_file(file)
        word_counts += count_words(text)
    top_5_words = word_counts.most_common(5)
    print("Top 5 words with the most number of occurrences:")
    for word, count in top_5_words:
        print(f"{word}: {count}")
if __name__ == "__main__":
    main()
```

reference_turn2:
Bạn nên kiểm tra cẩn thận xem logic song song có đúng không và chọn cách triển khai nhanh hơn.

Câu trả lời mẫu:
```
import os
import re
from collections import Counter
import concurrent.futures
def get_files_in_directory(directory):
    return [os.path.join(directory, f) for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f)) and f.endswith('.txt')]
def read_file(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        return file.read()
def count_words(text):
    words = re.findall(r'\w+', text.lower())
    return Counter(words)
def process_file(file):
    text = read_file(file)
    return count_words(text)
def main():
    directory = input("Enter the directory path: ")
    files = get_files_in_directory(directory)
    word_counts = Counter()
    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_word_counts = {executor.submit(process_file, file): file for file in files}
        for future in concurrent.futures.as_completed(future_word_counts):
            word_counts += future.result()
    top_5_words = word_counts.most_common(5)
    print("Top 5 words with the most number of occurrences:")
    for word, count in top_5_words:
        print(f"{word}: {count}")
if __name__ == "__main__":
    main()
```

response_turn2_a:
Dưới đây là phiên bản song song hóa (parallel) bằng `concurrent.futures.ProcessPoolExecutor`.  
Mỗi tệp được xử lý trên một CPU riêng, sau đó gộp kết quả về Counter chính.

```python
import os
import re
from collections import Counter
from concurrent.futures import ProcessPoolExecutor, as_completed

def dem_tu_trong_tep(duong_dan):
    """Đọc 1 tệp và trả về Counter từ."""
    try:
        with open(duong_dan, 'r', encoding='utf-8') as f:
            noi_dung = f.read().lower()
        tu_danh_sach = re.findall(r'\b\w+\b', noi_dung)
        return Counter(tu_danh_sach)
    except Exception as e:
        # Trả về Counter rỗng nếu lỗi
        print(f"Lỗi khi đọc {duong_dan}: {e}")
        return Counter()

def lay_5_tu_xuat_hien_nhieu_nhat_song_song(thu_muc, so_luong_cpu=None):
    """Song song hóa việc đếm từ trên nhiều CPU."""
    danh_sach_txt = [
        os.path.join(thu_muc, ten)
        for ten in os.listdir(thu_muc)
        if os.path.isfile(os.path.join(thu_muc, ten)) and ten.lower().endswith('.txt')
    ]

    if not danh_sach_txt:
        return []

    # Gộp tất cả Counter
    tong_counter = Counter()
    with ProcessPoolExecutor(max_workers=so_luong_cpu) as executor:
        # Map từng tệp
        for future in as_completed(executor.submit(dem_tu_trong_tep, tep) for tep in danh_sach_txt):
            tong_counter.update(future.result())

    return tong_counter.most_common(5)

if __name__ == "__main__":
    thu_muc_can_quet = input("Nhập đường dẫn thư mục chứa tệp văn bản: ").strip()
    top5 = lay_5_tu_xuat_hien_nhieu_nhat_song_song(thu_muc_can_quet)
    if top5:
        print("\nTop 5 từ xuất hiện nhiều nhất:")
        for tu, so_lan in top5:
            print(f"{tu}: {so_lan}")
    else:
        print("Không tìm thấy tệp .txt nào trong thư mục đã cho.")
```

