#include <iostream>

// Hàm đệ quy tìm số thứ n của dãy Tribonacci biến thể
long long tribonacciVariant(int n) {
    if (n == 0) return 0;      // Điều kiện dừng: số thứ 0
    if (n == 1 || n == 2)      // Điều kiện dừng: số thứ 1 và 2
        return -1;

    // Công thức truy hồi: T(n) = T(n-1) + T(n-2) + T(n-3)
    return tribonacciVariant(n - 1)
         + tribonacciVariant(n - 2)
         + tribonacciVariant(n - 3);
}

int main() {
